编写代码

打开刚才创建的main.cc，粘贴如下内容：

#include <iostream>
#include <fstream>
#include <random>
#include "include/api/model.h"
#include "include/api/context.h"
#include "include/api/status.h"
#include "include/api/types.h"
using mindspore::MSTensor;

char *ReadFile(const char *file, size_t *size) {
if (file == nullptr) {
std::cerr << "file is nullptr." << std::endl;
return nullptr;
}

std::ifstream ifs(file, std::ifstream::in | std::ifstream::binary);
if (!ifs.good()) {
std::cerr << "file: " << file << " is not exist." << std::endl;
return nullptr;
}

if (!ifs.is_open()) {
std::cerr << "file: " << file << " open failed." << std::endl;
return nullptr;
}

ifs.seekg(0, std::ios::end);
*size = ifs.tellg();
std::unique_ptr<char[]> buf(new (std::nothrow) char[*size]);
if (buf == nullptr) {
std::cerr << "malloc buf failed, file: " << file << std::endl;
ifs.close();
return nullptr;
}

ifs.seekg(0, std::ios::beg);
ifs.read(buf.get(), *size);
ifs.close();

return buf.release();
}

template <typename T, typename Distribution>
void GenerateRandomData(int size, void *data, Distribution distribution) {
std::mt19937 random_engine;
int elements_num = size / sizeof(T);
(void)std::generate_n(static_cast<T *>(data), elements_num,
[&distribution, &random_engine]() { return static_cast<T>(distribution(random_engine)); });
}

int main(int argc, const char **argv) {
// Read model file.
std::string model_path = "../model/mobilenetv2.ms";
size_t size = 0;
char *model_buf = ReadFile(model_path.c_str(), &size);
if (model_buf == nullptr) {
std::cerr << "Read model file failed." << std::endl;
return -1;
}

// Create and init context, add CPU device info
auto context = std::make_shared<mindspore::Context>();
if (context == nullptr) {
delete[](model_buf);
std::cerr << "New context failed." << std::endl;
return -1;
}
auto &device_list = context->MutableDeviceInfo();
auto device_info = std::make_shared<mindspore::CPUDeviceInfo>();
if (device_info == nullptr) {
delete[](model_buf);
std::cerr << "New CPUDeviceInfo failed." << std::endl;
return -1;
}
device_list.push_back(device_info);

// Create model
auto model = new (std::nothrow) mindspore::Model();
if (model == nullptr) {
delete[](model_buf);
std::cerr << "New Model failed." << std::endl;
return -1;
}

// Build model
auto build_ret = model->Build(model_buf, size, mindspore::kMindIR, context);
delete[](model_buf);
if (build_ret != mindspore::kSuccess) {
delete model;
std::cerr << "Build model error " << std::endl;
return -1;
}

// Get Input
auto inputs = model->GetInputs();
for (auto tensor : inputs) {
auto input_data = reinterpret_cast<float *>(tensor.MutableData());
if (input_data == nullptr) {
std::cerr << "MallocData for inTensor failed." << std::endl;
delete model;
return -1;
}
GenerateRandomData<float>(tensor.DataSize(), input_data, std::uniform_real_distribution<float>(0.1f, 1.0f));
}

// Predict
std::vector<MSTensor> outputs;
auto status = model->Predict(inputs, &outputs);
if (status != mindspore::kSuccess) {
std::cerr << "Inference error." << std::endl;
delete model;
return -1;
}

// Get Output Tensor Data.
std::cout << "\n------- print outputs ----------" << std::endl;
for (auto tensor : outputs) {
std::cout << "out tensor name is:" << tensor.Name() << "\nout tensor size is:" << tensor.DataSize()
<< "\nout tensor elements num is:" << tensor.ElementNum() << std::endl;
auto out_data = reinterpret_cast<float *>(tensor.MutableData());
std::cout << "output data is:";
for (int i = 0; i < tensor.ElementNum(); i++) {
std::cout << out_data[i] << " ";
}
std::cout << std::endl;
}
std::cout << "------- print end ----------\n" << std::endl;

// Delete model.
delete model;
return mindspore::kSuccess;
}

代码功能解析如下：

(1) 读取模型文件到buf

通过调用ReadFile函数，将模型文件读入到model_buf内存，用size变量保存模型的大小。

char *model_buf = ReadFile(model_path.c_str(), &size);

(2) 初始化Context配置

Context保存了模型推理时所需的相关配置，包括算子偏好、线程数、自动并发以及推理处理器相关的其他配置。
关于Context的详细说明，请参考Context的API接口说明。
在MindSpore Lite加载模型时，必须提供一个Context类的对象，所以在本例中，首先申请了一个Context类的对象context。

auto context = std::make_shared<mindspore::Context>();

接着，通过Context::MutableDeviceInfo接口，得到context对象的设备管理列表。

auto &device_list = context->MutableDeviceInfo();

在本例中，由于使用CPU进行推理，故需申请一个CPUDeviceInfo类的对象device_info。

auto device_info = std::make_shared<mindspore::CPUDeviceInfo>();

因为采用了CPU的默认设置，所以不需对device_info对象做任何设置，直接添加到context的设备管理列表。

device_list.push_back(device_info);

(3) 加载模型

首先创建一个Model类对象model，Model类定义了MindSpore Lite中的模型，用于计算图管理。
关于Model类的详细说明，可参考API文档。

auto model = new (std::nothrow) mindspore::Model();

接着调用Build接口传入模型，将模型编译至可在设备上运行的状态。
在加载编译完模型之后，被解析的模型信息已记录在model变量中，原先的模型文件内存model_buf可以释放。
由于model_buf是以char数组的方式申请的，故使用delete[]释放内存。

auto build_ret = model->Build(model_buf, size, mindspore::kMindIR, context);
delete[](model_buf);

(4) 传入数据

在执行模型推理前，需要设置推理的输入数据。
此例，通过Model.GetInputs接口，获取模型的所有输入张量。单个张量的格式为MSTensor。
关于MSTensor张量的详细说明，请参考MSTensor的API说明。

auto inputs = model->GetInputs();

通过张量的MutableData接口，可以获取张量的数据内存指针。
在本例中，模型的输入为浮点数格式，所以此处将指针强转为浮点指针。用户可根据自己模型的数据格式做不同处理，也可通过张量的DataType接口，得到该张量的数据类型。

auto input_data = reinterpret_cast<float *>(tensor.MutableData());

接着，通过数据指针，将我们要推理的数据传入张量内部。
在本例中我们传入的是随机生成的0.1至1的浮点数据，且数据呈平均分布。
在实际的推理中，用户在读取图片或音频等实际数据后，需进行算法特定的预处理操作，并将处理后的数据传入模型。

template <typename T, typename Distribution>
void GenerateRandomData(int size, void *data, Distribution distribution) {
std::mt19937 random_engine;
int elements_num = size / sizeof(T);
(void)std::generate_n(static_cast<T *>(data), elements_num,
[&distribution, &random_engine]() { return static_cast<T>(distribution(random_engine)); });
}

...

GenerateRandomData<float>(tensor.DataSize(), input_data, std::uniform_real_distribution<float>(0.1f, 1.0f));

(5) 执行推理

首先申请一个放置模型推理输出张量的数组outputs，然后调用模型推理接口Predict，将输入张量和输出张量作为参数。
在推理成功后，输出张量被保存在outputs内。

std::vector<MSTensor> outputs;
auto status = model->Predict(inputs, &outputs);

(6) 推理结果核验

通过MutableData得到输出张量的数据指针。
本例中，将它强转为浮点指针，用户可以根据自己模型的数据类型进行对应类型的转换，也可通过张量的DataType接口得到数据类型。

auto out_data = reinterpret_cast<float *>(tensor.MutableData());

在本例中，直接通过打印来观察推理输出结果的准确性。

for (int i = 0; i < tensor.ElementNum(); i++) {
std::cout << out_data[i] << " ";
}

(7) 释放model对象

delete model;

编译

进入build目录，输入cmake ..生成makefile文件，然后输入make编译工程。在编译成功后，可以在build目录下得到demo可执行程序。

运行推理程序

输入./demo执行demo程序，根据上文，我们知道demo程序将加载mobilenetv2.ms模型，并将随机生成的输入张量传递给模型进行推理，将推理后的输出张量的值进行打印。
推理成功，得到如下输出，可以看到输出张量包含1000个数值，这和我们在Netron可视化中得到的模型理解相一致的，由于本例传入的是0.1至1平均分布的数据（可视为噪声），所以输出并无分类特征：

link_directories(${CMAKE_CURRENT_SOURCE_DIR}/runtime/lib) # 添加库文件寻找路径

add_executable(demo main.cc) # 编译生成demo执行程序

# 声明demo执行程序需要链接的库，mindspore-lite为MindSpore Lite推理框架的动态库
target_link_libraries(
demo
mindspore-lite
pthread
ssp
)

